async(page)=>{
 const assert=(v,m)=>{if(!v)throw Error(m)},base='E:/Dr.RouteFit/prototype/records/2026-10-24-closure-update/normal-regression/',errors=[],checks=[];
 page.on('pageerror',err=>errors.push(err.message));await page.setViewportSize({width:1440,height:1000});await page.goto('http://127.0.0.1:4173/prototype/showcase.html');
 await page.locator('[data-action=reset]').click();await page.locator('[value=reset]').click();
 const state=()=>page.evaluate(()=>JSON.parse(sessionStorage.getItem('routefit-core-showcase-v1')));
 const submit=async(action,fields={},checked=false)=>{const f=page.locator(`[data-command=${action}]`);for(const [name,value]of Object.entries(fields))await f.locator(`[name=${name}]`).fill(String(value));if(checked)await f.locator('[name=confirmed]').check();await f.locator('[type=submit]').click();};
 for(const type of ['heavy','size','late']){await page.locator(`[data-action=preset-${type}]`).click();assert(await page.locator('[data-select]:enabled').count()===0,type+' unexpectedly feasible');}
 checks.push('超载、三轴尺寸、时窗冲突均无可派候选');await page.locator('[data-action=preset-normal]').click();await page.locator('[data-select=VAN]').click();await page.locator('[data-action=invalidate]').click();await submit('offer',{},true);assert((await state()).stage==='planned','stale plan offered');assert((await page.locator('#sc-message').innerText()).includes('过期'),'stale message');
 await page.locator('[data-action=preset-normal]').click();await page.locator('[data-select=VAN]').click();await page.locator('[name=weight]').fill('600');await page.locator('[data-tab=control]').click();await page.locator('[data-tab=dispatch]').click();assert(await page.locator('[name=weight]').inputValue()==='600','draft lost on tab switch');await submit('offer',{},true);assert((await state()).stage==='planned','dirty input offered');
 await page.locator('[data-action=preset-normal]').click();await page.locator('[data-select=VAN]').click();await page.screenshot({path:base+'dispatch-desktop.png',fullPage:true});await submit('offer',{},true);
 await page.locator('summary').filter({hasText:'无法接单'}).click();await submit('reject',{reason:'DEMO 驾驶员时间不符'});assert((await state()).stage==='planned','reject not returned');assert((await state()).orders[0].status==='pending','original mutated');
 await page.locator('[data-select=VAN]').click();await submit('offer',{},true);await submit('accept',{},true);await submit('release',{evidence:'DEMO-LOAD'},true);
 await submit('pickup',{count:5,evidence:'DEMO-PICKUP'});assert((await state()).stage==='released','wrong pickup advanced');await submit('pickup',{count:6,evidence:'DEMO-PICKUP'});await page.locator('[data-action=depart]').click();
 checks.push('方案版本变化、未评估编辑、司机拒绝回调度、点收差异阻断');await page.setViewportSize({width:390,height:844});await page.screenshot({path:base+'driver-mobile.png',fullPage:true});
 await submit('deliver',{count:4,amount:1,evidence:'DEMO-POD-A'});assert((await state()).stage==='transit','wrong money advanced');await submit('deliver',{count:4,amount:24,evidence:'DEMO-POD-A'});assert((await state()).orders[1].status==='pending','B delivered early');
 await page.reload();await page.locator('[data-tab=execution]').click();assert((await state()).orders[0].status==='delivered','refresh lost state');await submit('deliver',{count:2,amount:22,evidence:'DEMO-POD-B'});await submit('verify',{evidence:'DEMO-FINANCE'},true);
 await submit('remit',{amount:44,evidence:'DEMO-REMIT'});assert((await state()).stage==='verified','insurance omitted accepted');await submit('remit',{amount:46,evidence:'DEMO-REMIT'});await submit('reconcile',{amount:1,evidence:'DEMO-CLOSE'},true);assert((await state()).stage==='remitted','wrong reconciliation accepted');await submit('reconcile',{amount:46,evidence:'DEMO-CLOSE'},true);assert((await state()).stage==='closed','loop not closed');
 checks.push('逐单签收、刷新恢复、财务核验、足额交款及结清；保险不进入分成');
 assert((await page.locator('#sc-workspace').innerText()).includes('$8.80'),'commission wrong');assert((await page.locator('#sc-workspace').innerText()).includes('$35.20'),'driver income wrong');
 const before=JSON.stringify(await state());await page.locator('[data-tab=control]').click();assert(await page.locator('#sc-workspace button').count()===0,'control has write controls');await page.locator('[data-action=reset]').click();await page.locator('[value=cancel]').click();assert(JSON.stringify(await state())===before,'reset cancel mutated');
 await page.setViewportSize({width:1440,height:1000});await page.screenshot({path:base+'control-closed.png',fullPage:true});
 for(const width of [360,390,1440]){await page.setViewportSize({width,height:900});for(const tab of ['dispatch','execution','finance','control','events']){await page.locator(`[data-tab=${tab}]`).click();assert(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),'overflow '+tab+width);}}
 const downloadEvent=page.waitForEvent('download');await page.locator('[data-action=export]').click();const download=await downloadEvent;assert(download.suggestedFilename()==='routefit-demo-record.json','export filename wrong');await download.saveAs(base+'exported-demo-record.json');checks.push('只读中控无业务写入口、重置取消不变更、三种宽度五个工作席无横向溢出、记录 JSON 实际下载');
 assert(await page.locator('img').evaluateAll(xs=>xs.every(x=>x.complete&&x.naturalWidth>0)),'logo failed');assert(errors.length===0,errors.join('\n'));
 await page.setViewportSize({width:1440,height:1000});await page.locator('[data-tab=finance]').click();return {status:'PASS',checks,pageErrors:errors,finalState:await state()};
}

